export const files: Record<string, string> = {
  ".env.example": "# Applicant Tracker needs no environment variables or API keys.\n# Everything — job postings, candidates, and activity notes — is stored\n# locally in your browser (localStorage). Nothing is sent to a server.\n",
  "README.md": "# Applicant Tracker\n\nA lightweight hiring pipeline (ATS): post open roles, collect candidates\nagainst them, and move people through a kanban board as they interview.\n\n## Features\n\n- Job postings (title, department, open/closed status) that you can\n  create, edit, and close — candidates are tagged against one.\n- Candidates with a name, email, role applied for, freeform resume\n  notes, and a 0-5 star rating.\n- A kanban board — Applied, Screening, Interview, Offer, Hired,\n  Rejected — with draggable candidate cards and a live count per stage.\n- A role filter above the board to see only candidates for one job\n  posting.\n- Click a candidate to open a detail panel: editable notes and rating,\n  plus a timestamped activity log you can append to over time (e.g.\n  \"Phone screen went well, moving to onsite\").\n\n## Demo data\n\nThis ships with a handful of realistic-looking demo job postings and\ncandidates so the board isn't empty the first time you open it (see\n`src/lib/seedData.ts`). **None of it is real** — it's fake names,\nemails, and notes. It's stored in `localStorage` exactly like anything\nyou create yourself, so feel free to edit or delete every bit of it; it\nwon't come back once you do (it's only ever seeded once, on the very\nfirst load).\n\n## Getting started\n\n```bash\nnpm install\nnpm run dev\n```\n\n## Build\n\n```bash\nnpm run build\n```\n\n## Data storage\n\nJob postings and candidates are stored in your browser's\n`localStorage`. Nothing leaves your device, and there is no account or\nsign-in.\n",
  "index.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Applicant Tracker</title>\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.tsx\"></script>\n  </body>\n</html>\n",
  "package.json": "{\n  \"name\": \"applicant-tracker\",\n  \"private\": true,\n  \"version\": \"1.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"vite build\",\n    \"preview\": \"vite preview\"\n  },\n  \"dependencies\": {\n    \"lucide-react\": \"^0.417.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\"\n  },\n  \"devDependencies\": {\n    \"@types/react\": \"^18.3.3\",\n    \"@types/react-dom\": \"^18.3.0\",\n    \"@vitejs/plugin-react\": \"^4.3.1\",\n    \"autoprefixer\": \"^10.4.19\",\n    \"postcss\": \"^8.4.40\",\n    \"tailwindcss\": \"^3.4.7\",\n    \"typescript\": \"^5.5.4\",\n    \"vite\": \"^5.4.0\"\n  }\n}\n",
  "postcss.config.js": "export default {\n  plugins: {\n    tailwindcss: {},\n    autoprefixer: {},\n  },\n};\n",
  "src/App.tsx": "import { useEffect, useState } from \"react\";\nimport type { Candidate, JobPosting, Stage } from \"./types\";\nimport { loadCandidates, loadJobPostings, saveCandidates, saveJobPostings } from \"./lib/storage\";\nimport { NavBar, type NavView } from \"./components/NavBar\";\nimport { KanbanBoard } from \"./components/KanbanBoard\";\nimport { JobPostingsPanel } from \"./components/JobPostingsPanel\";\nimport { NewCandidateModal } from \"./components/NewCandidateModal\";\nimport { CandidateDetailModal } from \"./components/CandidateDetailModal\";\n\nexport default function App() {\n  const [jobPostings, setJobPostings] = useState<JobPosting[]>(() => loadJobPostings());\n  const [candidates, setCandidates] = useState<Candidate[]>(() => loadCandidates());\n  const [view, setView] = useState<NavView>(\"board\");\n  const [creatingCandidate, setCreatingCandidate] = useState(false);\n  const [openCandidateId, setOpenCandidateId] = useState<string | null>(null);\n\n  useEffect(() => saveJobPostings(jobPostings), [jobPostings]);\n  useEffect(() => saveCandidates(candidates), [candidates]);\n\n  function addJobPosting(data: { title: string; department: string }) {\n    setJobPostings((prev) => [...prev, { ...data, id: crypto.randomUUID(), status: \"open\", createdAt: Date.now() }]);\n  }\n  function updateJobPosting(id: string, data: { title: string; department: string }) {\n    setJobPostings((prev) => prev.map((j) => (j.id === id ? { ...j, ...data } : j)));\n  }\n  function toggleJobStatus(id: string) {\n    setJobPostings((prev) => prev.map((j) => (j.id === id ? { ...j, status: j.status === \"open\" ? \"closed\" : \"open\" } : j)));\n  }\n  function deleteJobPosting(id: string) {\n    setJobPostings((prev) => prev.filter((j) => j.id !== id));\n  }\n\n  function createCandidate(data: { name: string; email: string; roleId: string; resumeNotes: string; rating: number }) {\n    const candidate: Candidate = {\n      id: crypto.randomUUID(),\n      name: data.name,\n      email: data.email,\n      roleId: data.roleId,\n      resumeNotes: data.resumeNotes,\n      rating: data.rating,\n      stage: \"Applied\",\n      activity: [{ id: crypto.randomUUID(), text: \"Application received.\", createdAt: Date.now() }],\n      createdAt: Date.now(),\n    };\n    setCandidates((prev) => [...prev, candidate]);\n    setCreatingCandidate(false);\n  }\n\n  function moveStage(candidateId: string, stage: Stage) {\n    setCandidates((prev) => prev.map((c) => (c.id === candidateId ? { ...c, stage } : c)));\n  }\n\n  function updateCandidate(id: string, data: { resumeNotes: string; rating: number; roleId: string }) {\n    setCandidates((prev) => prev.map((c) => (c.id === id ? { ...c, ...data } : c)));\n  }\n\n  function addActivity(id: string, text: string) {\n    setCandidates((prev) =>\n      prev.map((c) =>\n        c.id === id ? { ...c, activity: [...c.activity, { id: crypto.randomUUID(), text, createdAt: Date.now() }] } : c\n      )\n    );\n  }\n\n  function deleteCandidate(id: string) {\n    setCandidates((prev) => prev.filter((c) => c.id !== id));\n    setOpenCandidateId((current) => (current === id ? null : current));\n  }\n\n  const openCandidate = candidates.find((c) => c.id === openCandidateId) ?? null;\n\n  return (\n    <div className=\"min-h-screen bg-gradient-to-b from-violet-50/50 via-slate-50 to-slate-50\">\n      <NavBar view={view} onNavigate={setView} onNewCandidate={() => setCreatingCandidate(true)} />\n\n      <main className=\"mx-auto max-w-6xl px-4 py-6\">\n        {view === \"board\" ? (\n          <KanbanBoard\n            candidates={candidates}\n            jobPostings={jobPostings}\n            onOpenCandidate={setOpenCandidateId}\n            onMoveStage={moveStage}\n          />\n        ) : (\n          <JobPostingsPanel\n            jobPostings={jobPostings}\n            candidates={candidates}\n            onAdd={addJobPosting}\n            onUpdate={updateJobPosting}\n            onToggleStatus={toggleJobStatus}\n            onDelete={deleteJobPosting}\n          />\n        )}\n      </main>\n\n      {creatingCandidate && (\n        <NewCandidateModal\n          jobPostings={jobPostings}\n          onCreate={createCandidate}\n          onClose={() => setCreatingCandidate(false)}\n          onGoToJobs={() => {\n            setCreatingCandidate(false);\n            setView(\"jobs\");\n          }}\n        />\n      )}\n\n      {openCandidate && (\n        <CandidateDetailModal\n          candidate={openCandidate}\n          jobPostings={jobPostings}\n          onClose={() => setOpenCandidateId(null)}\n          onUpdate={(data) => updateCandidate(openCandidate.id, data)}\n          onStageChange={(stage) => moveStage(openCandidate.id, stage)}\n          onAddActivity={(text) => addActivity(openCandidate.id, text)}\n          onDelete={() => deleteCandidate(openCandidate.id)}\n        />\n      )}\n    </div>\n  );\n}\n",
  "src/components/CandidateCard.tsx": "import type { Candidate, JobPosting } from \"../types\";\nimport { StarRating } from \"./StarRating\";\n\ninterface Props {\n  candidate: Candidate;\n  role: JobPosting | undefined;\n  onClick: () => void;\n  onDragStart: (e: React.DragEvent) => void;\n}\n\nexport function CandidateCard({ candidate, role, onClick, onDragStart }: Props) {\n  return (\n    <button\n      type=\"button\"\n      draggable\n      onDragStart={onDragStart}\n      onClick={onClick}\n      className=\"w-full cursor-grab rounded-xl border border-slate-200 bg-white p-3.5 text-left shadow-sm shadow-slate-900/[0.03] transition-all duration-150 hover:-translate-y-0.5 hover:border-violet-200 hover:shadow-md active:cursor-grabbing\"\n    >\n      <p className=\"truncate text-sm font-medium text-slate-900\">{candidate.name}</p>\n      <p className=\"truncate text-xs text-slate-500\">{role?.title ?? \"No role\"}</p>\n      <div className=\"mt-1.5\">\n        <StarRating rating={candidate.rating} />\n      </div>\n    </button>\n  );\n}\n",
  "src/components/CandidateDetailModal.tsx": "import { useState } from \"react\";\nimport { Plus, Trash2, X } from \"lucide-react\";\nimport type { Candidate, JobPosting, Stage } from \"../types\";\nimport { STAGES } from \"../types\";\nimport { StarRating } from \"./StarRating\";\n\ninterface Props {\n  candidate: Candidate;\n  jobPostings: JobPosting[];\n  onClose: () => void;\n  onUpdate: (data: { resumeNotes: string; rating: number; roleId: string }) => void;\n  onStageChange: (stage: Stage) => void;\n  onAddActivity: (text: string) => void;\n  onDelete: () => void;\n}\n\nexport function CandidateDetailModal({ candidate, jobPostings, onClose, onUpdate, onStageChange, onAddActivity, onDelete }: Props) {\n  const [notes, setNotes] = useState(candidate.resumeNotes);\n  const [rating, setRating] = useState(candidate.rating);\n  const [roleId, setRoleId] = useState(candidate.roleId);\n  const [activityText, setActivityText] = useState(\"\");\n  const [confirmingDelete, setConfirmingDelete] = useState(false);\n\n  function commit(patch: Partial<{ resumeNotes: string; rating: number; roleId: string }>) {\n    onUpdate({ resumeNotes: notes, rating, roleId, ...patch });\n  }\n\n  function submitActivity(e: React.FormEvent) {\n    e.preventDefault();\n    const trimmed = activityText.trim();\n    if (!trimmed) return;\n    onAddActivity(trimmed);\n    setActivityText(\"\");\n  }\n\n  const sortedActivity = [...candidate.activity].sort((a, b) => b.createdAt - a.createdAt);\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4\" onClick={onClose}>\n      <div\n        onClick={(e) => e.stopPropagation()}\n        className=\"flex max-h-[85vh] w-full max-w-lg flex-col overflow-hidden rounded-2xl bg-white shadow-xl\"\n      >\n        <div className=\"flex items-start justify-between gap-3 border-b border-slate-200 p-4 sm:p-5\">\n          <div className=\"min-w-0\">\n            <p className=\"truncate text-base font-semibold text-slate-900\">{candidate.name}</p>\n            <p className=\"truncate text-xs text-slate-500\">{candidate.email}</p>\n          </div>\n          <button\n            type=\"button\"\n            onClick={onClose}\n            aria-label=\"Close\"\n            className=\"flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600\"\n          >\n            <X className=\"h-5 w-5\" />\n          </button>\n        </div>\n\n        <div className=\"flex-1 space-y-4 overflow-y-auto p-4 sm:p-5\">\n          <div className=\"grid grid-cols-1 gap-3 sm:grid-cols-2\">\n            <div>\n              <label className=\"mb-1 block text-xs font-medium text-slate-600\">Role applied for</label>\n              <select\n                value={roleId}\n                onChange={(e) => {\n                  setRoleId(e.target.value);\n                  commit({ roleId: e.target.value });\n                }}\n                className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-violet-400\"\n              >\n                {jobPostings.map((j) => (\n                  <option key={j.id} value={j.id}>\n                    {j.title}\n                  </option>\n                ))}\n              </select>\n            </div>\n            <div>\n              <label className=\"mb-1 block text-xs font-medium text-slate-600\">Stage</label>\n              <select\n                value={candidate.stage}\n                onChange={(e) => onStageChange(e.target.value as Stage)}\n                className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-violet-400\"\n              >\n                {STAGES.map((s) => (\n                  <option key={s} value={s}>\n                    {s}\n                  </option>\n                ))}\n              </select>\n            </div>\n          </div>\n\n          <div>\n            <label className=\"mb-1 block text-xs font-medium text-slate-600\">Rating</label>\n            <StarRating\n              rating={rating}\n              size=\"md\"\n              onChange={(n) => {\n                setRating(n);\n                commit({ rating: n });\n              }}\n            />\n          </div>\n\n          <div>\n            <label className=\"mb-1 block text-xs font-medium text-slate-600\">Resume notes</label>\n            <textarea\n              value={notes}\n              onChange={(e) => setNotes(e.target.value)}\n              onBlur={() => commit({ resumeNotes: notes })}\n              rows={4}\n              className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-violet-400\"\n            />\n          </div>\n\n          <div>\n            <p className=\"mb-2 text-xs font-medium uppercase tracking-wide text-slate-400\">Activity log</p>\n            <form onSubmit={submitActivity} className=\"mb-3 flex gap-2\">\n              <input\n                value={activityText}\n                onChange={(e) => setActivityText(e.target.value)}\n                placeholder=\"Log a note or update...\"\n                className=\"flex-1 rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-violet-400\"\n              />\n              <button\n                type=\"submit\"\n                className=\"flex items-center gap-1 rounded-lg bg-slate-900 px-3 py-2 text-sm font-medium text-white hover:bg-slate-800\"\n              >\n                <Plus className=\"h-3.5 w-3.5\" /> Add\n              </button>\n            </form>\n            {sortedActivity.length === 0 ? (\n              <p className=\"text-xs text-slate-400\">No activity logged yet.</p>\n            ) : (\n              <ul className=\"space-y-2\">\n                {sortedActivity.map((entry) => (\n                  <li key={entry.id} className=\"rounded-lg bg-slate-50 p-2.5 text-sm text-slate-700\">\n                    <p>{entry.text}</p>\n                    <p className=\"mt-1 text-[11px] text-slate-400\">{new Date(entry.createdAt).toLocaleString()}</p>\n                  </li>\n                ))}\n              </ul>\n            )}\n          </div>\n        </div>\n\n        <div className=\"border-t border-slate-200 p-4 sm:p-5\">\n          {confirmingDelete ? (\n            <div className=\"flex flex-wrap items-center justify-end gap-2\">\n              <span className=\"mr-auto text-sm text-slate-500\">Delete this candidate?</span>\n              <button\n                type=\"button\"\n                onClick={onDelete}\n                className=\"rounded-lg bg-red-600 px-3 py-2 text-sm font-medium text-white transition-colors hover:bg-red-700\"\n              >\n                Delete\n              </button>\n              <button\n                type=\"button\"\n                onClick={() => setConfirmingDelete(false)}\n                className=\"rounded-lg px-3 py-2 text-sm text-slate-600 transition-colors hover:bg-slate-100\"\n              >\n                Cancel\n              </button>\n            </div>\n          ) : (\n            <button\n              type=\"button\"\n              onClick={() => setConfirmingDelete(true)}\n              className=\"flex items-center gap-1.5 text-sm text-red-600 transition-colors hover:text-red-700\"\n            >\n              <Trash2 className=\"h-4 w-4\" /> Delete candidate\n            </button>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n}\n",
  "src/components/JobPostingsPanel.tsx": "import { useState } from \"react\";\nimport { Pencil, Plus, Trash2 } from \"lucide-react\";\nimport type { Candidate, JobPosting, JobStatus } from \"../types\";\n\ninterface Props {\n  jobPostings: JobPosting[];\n  candidates: Candidate[];\n  onAdd: (data: { title: string; department: string }) => void;\n  onUpdate: (id: string, data: { title: string; department: string }) => void;\n  onToggleStatus: (id: string) => void;\n  onDelete: (id: string) => void;\n}\n\ninterface FormState {\n  title: string;\n  department: string;\n}\nconst EMPTY_FORM: FormState = { title: \"\", department: \"\" };\n\nconst STATUS_STYLES: Record<JobStatus, string> = {\n  open: \"bg-emerald-100 text-emerald-700\",\n  closed: \"bg-slate-100 text-slate-600\",\n};\n\nexport function JobPostingsPanel({ jobPostings, candidates, onAdd, onUpdate, onToggleStatus, onDelete }: Props) {\n  const [adding, setAdding] = useState(false);\n  const [form, setForm] = useState<FormState>(EMPTY_FORM);\n  const [editingId, setEditingId] = useState<string | null>(null);\n  const [editForm, setEditForm] = useState<FormState>(EMPTY_FORM);\n  const [confirmingId, setConfirmingId] = useState<string | null>(null);\n  const [error, setError] = useState(\"\");\n\n  function candidateCount(roleId: string) {\n    return candidates.filter((c) => c.roleId === roleId).length;\n  }\n\n  function submitAdd(e: React.FormEvent) {\n    e.preventDefault();\n    if (!form.title.trim()) {\n      setError(\"Give the role a title.\");\n      return;\n    }\n    onAdd({ title: form.title.trim(), department: form.department.trim() });\n    setForm(EMPTY_FORM);\n    setAdding(false);\n    setError(\"\");\n  }\n\n  function startEdit(j: JobPosting) {\n    setEditingId(j.id);\n    setEditForm({ title: j.title, department: j.department });\n  }\n\n  function submitEdit(e: React.FormEvent) {\n    e.preventDefault();\n    if (!editingId) return;\n    if (!editForm.title.trim()) {\n      setError(\"Give the role a title.\");\n      return;\n    }\n    onUpdate(editingId, { title: editForm.title.trim(), department: editForm.department.trim() });\n    setEditingId(null);\n    setError(\"\");\n  }\n\n  return (\n    <div className=\"mx-auto max-w-2xl\">\n      <div className=\"mb-5 flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between\">\n        <div>\n          <h2 className=\"text-lg font-semibold text-slate-900\">Job postings</h2>\n          <p className=\"mt-0.5 text-sm text-slate-500\">Candidates are tagged against one of these roles.</p>\n        </div>\n        {!adding && (\n          <button\n            type=\"button\"\n            onClick={() => setAdding(true)}\n            className=\"flex shrink-0 items-center justify-center gap-1.5 rounded-lg bg-slate-900 px-3.5 py-2 text-sm font-medium text-white transition-all duration-150 hover:bg-slate-800 active:scale-[0.98]\"\n          >\n            <Plus className=\"h-4 w-4\" /> Add role\n          </button>\n        )}\n      </div>\n\n      {error && <p className=\"mb-3 text-sm text-red-600\">{error}</p>}\n\n      {adding && (\n        <form onSubmit={submitAdd} className=\"mb-4 space-y-2 rounded-xl border border-slate-200 p-4\">\n          <input\n            autoFocus\n            value={form.title}\n            onChange={(e) => setForm({ ...form, title: e.target.value })}\n            placeholder=\"Role title\"\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-violet-400\"\n          />\n          <input\n            value={form.department}\n            onChange={(e) => setForm({ ...form, department: e.target.value })}\n            placeholder=\"Department\"\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-violet-400\"\n          />\n          <div className=\"flex justify-end gap-2\">\n            <button\n              type=\"button\"\n              onClick={() => {\n                setAdding(false);\n                setForm(EMPTY_FORM);\n                setError(\"\");\n              }}\n              className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\"\n            >\n              Cancel\n            </button>\n            <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n              Save\n            </button>\n          </div>\n        </form>\n      )}\n\n      {jobPostings.length === 0 && !adding ? (\n        <div className=\"flex flex-col items-center gap-3 rounded-2xl border border-dashed border-violet-200 bg-white/60 p-10 text-center shadow-sm sm:p-12\">\n          <span className=\"flex h-12 w-12 items-center justify-center rounded-full bg-violet-100 text-violet-600\">\n            <Plus className=\"h-5 w-5\" />\n          </span>\n          <div>\n            <p className=\"text-sm font-medium text-slate-700\">No job postings yet</p>\n            <p className=\"mt-1 text-sm text-slate-500\">Add a role before you start tagging candidates to it.</p>\n          </div>\n          <button\n            type=\"button\"\n            onClick={() => setAdding(true)}\n            className=\"mt-1 flex items-center gap-1.5 rounded-lg bg-slate-900 px-4 py-2 text-sm font-medium text-white transition-all duration-150 hover:bg-slate-800 active:scale-[0.98]\"\n          >\n            <Plus className=\"h-4 w-4\" /> Add your first role\n          </button>\n        </div>\n      ) : (\n        <div className=\"space-y-2\">\n          {jobPostings.map((j) => (\n            <div key={j.id} className=\"rounded-xl border border-slate-200 p-3\">\n              {editingId === j.id ? (\n                <form onSubmit={submitEdit} className=\"space-y-2\">\n                  <input\n                    autoFocus\n                    value={editForm.title}\n                    onChange={(e) => setEditForm({ ...editForm, title: e.target.value })}\n                    className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-violet-400\"\n                  />\n                  <input\n                    value={editForm.department}\n                    onChange={(e) => setEditForm({ ...editForm, department: e.target.value })}\n                    className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-violet-400\"\n                  />\n                  <div className=\"flex justify-end gap-2\">\n                    <button type=\"button\" onClick={() => setEditingId(null)} className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\">\n                      Cancel\n                    </button>\n                    <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n                      Save\n                    </button>\n                  </div>\n                </form>\n              ) : (\n                <div className=\"flex items-start justify-between gap-2\">\n                  <div>\n                    <div className=\"flex items-center gap-2\">\n                      <p className=\"text-sm font-medium text-slate-900\">{j.title}</p>\n                      <button\n                        type=\"button\"\n                        onClick={() => onToggleStatus(j.id)}\n                        title=\"Click to toggle open/closed\"\n                        className={`rounded-full px-2 py-0.5 text-[11px] font-medium capitalize ${STATUS_STYLES[j.status]}`}\n                      >\n                        {j.status}\n                      </button>\n                    </div>\n                    {j.department && <p className=\"text-xs text-slate-500\">{j.department}</p>}\n                    <p className=\"mt-0.5 text-xs text-slate-400\">\n                      {candidateCount(j.id)} candidate{candidateCount(j.id) === 1 ? \"\" : \"s\"}\n                    </p>\n                  </div>\n                  {confirmingId === j.id ? (\n                    <div className=\"flex shrink-0 items-center gap-1.5\">\n                      <button\n                        type=\"button\"\n                        onClick={() => {\n                          onDelete(j.id);\n                          setConfirmingId(null);\n                        }}\n                        className=\"text-xs font-medium text-red-600\"\n                      >\n                        Delete\n                      </button>\n                      <button type=\"button\" onClick={() => setConfirmingId(null)} className=\"text-xs text-slate-400\">\n                        Cancel\n                      </button>\n                    </div>\n                  ) : (\n                    <div className=\"flex shrink-0 items-center gap-1 text-slate-400\">\n                      <button\n                        type=\"button\"\n                        onClick={() => startEdit(j)}\n                        title=\"Edit\"\n                        className=\"rounded-lg p-2 transition-colors hover:bg-slate-100 hover:text-slate-700\"\n                      >\n                        <Pencil className=\"h-3.5 w-3.5\" />\n                      </button>\n                      <button\n                        type=\"button\"\n                        onClick={() => setConfirmingId(j.id)}\n                        title=\"Delete\"\n                        className=\"rounded-lg p-2 transition-colors hover:bg-red-50 hover:text-red-600\"\n                      >\n                        <Trash2 className=\"h-3.5 w-3.5\" />\n                      </button>\n                    </div>\n                  )}\n                </div>\n              )}\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/components/KanbanBoard.tsx": "import { useMemo, useState } from \"react\";\nimport type { Candidate, JobPosting, Stage } from \"../types\";\nimport { STAGES } from \"../types\";\nimport { CandidateCard } from \"./CandidateCard\";\n\ninterface Props {\n  candidates: Candidate[];\n  jobPostings: JobPosting[];\n  onOpenCandidate: (id: string) => void;\n  onMoveStage: (candidateId: string, stage: Stage) => void;\n}\n\nconst STAGE_COLORS: Record<Stage, string> = {\n  Applied: \"border-slate-300\",\n  Screening: \"border-blue-300\",\n  Interview: \"border-violet-300\",\n  Offer: \"border-amber-300\",\n  Hired: \"border-emerald-300\",\n  Rejected: \"border-red-300\",\n};\n\nexport function KanbanBoard({ candidates, jobPostings, onOpenCandidate, onMoveStage }: Props) {\n  const [dragOverStage, setDragOverStage] = useState<Stage | null>(null);\n  const [roleFilter, setRoleFilter] = useState<string>(\"all\");\n\n  const visible = useMemo(() => {\n    if (roleFilter === \"all\") return candidates;\n    return candidates.filter((c) => c.roleId === roleFilter);\n  }, [candidates, roleFilter]);\n\n  function handleDrop(e: React.DragEvent, stage: Stage) {\n    e.preventDefault();\n    setDragOverStage(null);\n    const candidateId = e.dataTransfer.getData(\"text/plain\");\n    if (candidateId) onMoveStage(candidateId, stage);\n  }\n\n  return (\n    <div>\n      <div className=\"mb-5 flex flex-wrap items-center gap-2\">\n        {STAGES.map((stage) => {\n          const count = visible.filter((c) => c.stage === stage).length;\n          return (\n            <div\n              key={stage}\n              className=\"flex items-center gap-1.5 rounded-full border border-violet-100 bg-white px-3.5 py-1.5 text-xs font-medium text-slate-600 shadow-sm shadow-violet-900/5\"\n            >\n              {stage}\n              <span className=\"rounded-full bg-violet-100 px-1.5 py-0.5 text-[11px] font-semibold text-violet-700\">{count}</span>\n            </div>\n          );\n        })}\n        <select\n          value={roleFilter}\n          onChange={(e) => setRoleFilter(e.target.value)}\n          className=\"ml-auto rounded-lg border border-slate-200 bg-white px-2.5 py-2 text-xs outline-none transition-colors focus:border-violet-400\"\n        >\n          <option value=\"all\">All roles</option>\n          {jobPostings.map((j) => (\n            <option key={j.id} value={j.id}>\n              {j.title}\n            </option>\n          ))}\n        </select>\n      </div>\n\n      <div className=\"-mx-4 flex gap-3 overflow-x-auto px-4 pb-4 sm:mx-0 sm:px-0\">\n        {STAGES.map((stage) => {\n          const stageCandidates = visible.filter((c) => c.stage === stage);\n          return (\n            <div\n              key={stage}\n              onDragOver={(e) => {\n                e.preventDefault();\n                setDragOverStage(stage);\n              }}\n              onDragLeave={() => setDragOverStage(null)}\n              onDrop={(e) => handleDrop(e, stage)}\n              className={`w-[72vw] max-w-64 shrink-0 rounded-xl border-t-2 bg-slate-100/60 p-2.5 transition-colors sm:w-64 ${STAGE_COLORS[stage]} ${\n                dragOverStage === stage ? \"bg-violet-50\" : \"\"\n              }`}\n            >\n              <div className=\"mb-2 flex items-center justify-between px-1\">\n                <p className=\"text-sm font-semibold text-slate-700\">{stage}</p>\n                <span className=\"rounded-full bg-slate-200/70 px-1.5 py-0.5 text-[11px] font-semibold text-slate-500\">\n                  {stageCandidates.length}\n                </span>\n              </div>\n              <div className=\"min-h-16 space-y-2\">\n                {stageCandidates.length === 0 ? (\n                  <div className=\"flex min-h-16 items-center justify-center rounded-lg border border-dashed border-slate-300/70 px-2 text-center text-xs text-slate-400\">\n                    No candidates\n                  </div>\n                ) : (\n                  stageCandidates.map((c) => (\n                    <CandidateCard\n                      key={c.id}\n                      candidate={c}\n                      role={jobPostings.find((j) => j.id === c.roleId)}\n                      onClick={() => onOpenCandidate(c.id)}\n                      onDragStart={(e) => e.dataTransfer.setData(\"text/plain\", c.id)}\n                    />\n                  ))\n                )}\n              </div>\n            </div>\n          );\n        })}\n      </div>\n      <p className=\"mt-2 text-xs text-slate-400\">\n        Demo data ships with this template (see README) — everything here is editable and deletable.\n      </p>\n    </div>\n  );\n}\n",
  "src/components/NavBar.tsx": "import { Briefcase, Kanban, Plus } from \"lucide-react\";\n\nexport type NavView = \"board\" | \"jobs\";\n\ninterface Props {\n  view: NavView;\n  onNavigate: (view: NavView) => void;\n  onNewCandidate: () => void;\n}\n\nfunction navClass(active: boolean) {\n  return `flex w-full items-center justify-center gap-1.5 rounded-full px-3 py-2 text-sm font-medium transition-colors sm:w-auto sm:justify-start sm:py-1.5 ${\n    active ? \"bg-violet-600 text-white shadow-sm shadow-violet-500/30\" : \"text-slate-500 hover:bg-violet-50 hover:text-violet-700\"\n  }`;\n}\n\nexport function NavBar({ view, onNavigate, onNewCandidate }: Props) {\n  return (\n    <header className=\"border-b border-violet-100/70 bg-white/90 backdrop-blur-sm\">\n      <div className=\"mx-auto flex max-w-6xl flex-wrap items-center gap-3 px-4 py-3 sm:py-3.5\">\n        <h1 className=\"flex items-center gap-2 text-base font-bold tracking-tight text-slate-900\">\n          <span className=\"flex h-8 w-8 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-violet-500 to-indigo-600 text-white shadow-sm shadow-violet-500/30\">\n            <Briefcase className=\"h-4 w-4\" />\n          </span>\n          <span>Applicant Tracker</span>\n        </h1>\n        <button\n          type=\"button\"\n          onClick={onNewCandidate}\n          className=\"ml-auto flex items-center gap-1.5 rounded-full bg-gradient-to-r from-violet-600 to-indigo-600 px-4 py-2 text-sm font-semibold text-white shadow-sm shadow-violet-500/30 transition-all duration-150 hover:-translate-y-0.5 hover:shadow-md active:translate-y-0 sm:order-3\"\n        >\n          <Plus className=\"h-4 w-4\" /> New candidate\n        </button>\n        <nav className=\"order-3 grid w-full grid-cols-2 gap-1.5 sm:order-2 sm:flex sm:w-auto sm:gap-1\">\n          <button type=\"button\" onClick={() => onNavigate(\"board\")} className={navClass(view === \"board\")}>\n            <Kanban className=\"h-3.5 w-3.5\" /> Board\n          </button>\n          <button type=\"button\" onClick={() => onNavigate(\"jobs\")} className={navClass(view === \"jobs\")}>\n            <Briefcase className=\"h-3.5 w-3.5\" /> Job postings\n          </button>\n        </nav>\n      </div>\n    </header>\n  );\n}\n",
  "src/components/NewCandidateModal.tsx": "import { useState } from \"react\";\nimport { X } from \"lucide-react\";\nimport type { JobPosting } from \"../types\";\nimport { StarRating } from \"./StarRating\";\n\ninterface Props {\n  jobPostings: JobPosting[];\n  onCreate: (data: { name: string; email: string; roleId: string; resumeNotes: string; rating: number }) => void;\n  onClose: () => void;\n  onGoToJobs: () => void;\n}\n\nexport function NewCandidateModal({ jobPostings, onCreate, onClose, onGoToJobs }: Props) {\n  const [name, setName] = useState(\"\");\n  const [email, setEmail] = useState(\"\");\n  const [roleId, setRoleId] = useState(jobPostings[0]?.id ?? \"\");\n  const [resumeNotes, setResumeNotes] = useState(\"\");\n  const [rating, setRating] = useState(0);\n  const [error, setError] = useState(\"\");\n\n  function handleSubmit(e: React.FormEvent) {\n    e.preventDefault();\n    if (!name.trim()) {\n      setError(\"Give the candidate a name.\");\n      return;\n    }\n    if (!roleId) {\n      setError(\"Pick a role.\");\n      return;\n    }\n    onCreate({ name: name.trim(), email: email.trim(), roleId, resumeNotes: resumeNotes.trim(), rating });\n  }\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4\" onClick={onClose}>\n      <div\n        onClick={(e) => e.stopPropagation()}\n        className=\"flex max-h-[90vh] w-full max-w-md flex-col overflow-hidden rounded-2xl bg-white shadow-xl\"\n      >\n        <div className=\"flex items-center justify-between gap-3 border-b border-slate-100 px-5 py-4 sm:px-6\">\n          <h2 className=\"text-lg font-semibold text-slate-900\">New candidate</h2>\n          <button\n            type=\"button\"\n            onClick={onClose}\n            aria-label=\"Close\"\n            className=\"flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600\"\n          >\n            <X className=\"h-5 w-5\" />\n          </button>\n        </div>\n\n        {jobPostings.length === 0 ? (\n          <div className=\"px-5 py-8 text-center sm:px-6\">\n            <p className=\"mb-3 text-sm text-slate-600\">Add a job posting before adding candidates.</p>\n            <button\n              type=\"button\"\n              onClick={onGoToJobs}\n              className=\"rounded-lg bg-slate-900 px-4 py-2.5 text-sm font-medium text-white transition-all duration-150 hover:bg-slate-800 active:scale-[0.98]\"\n            >\n              Go to Job postings\n            </button>\n          </div>\n        ) : (\n          <>\n            <form id=\"new-candidate-form\" onSubmit={handleSubmit} className=\"min-h-0 flex-1 space-y-3 overflow-y-auto px-5 py-4 sm:px-6\">\n              <input\n                autoFocus\n                value={name}\n                onChange={(e) => setName(e.target.value)}\n                placeholder=\"Candidate name\"\n                className=\"w-full rounded-lg border border-slate-200 px-3 py-2.5 text-sm outline-none transition-colors focus:border-violet-400 focus:ring-2 focus:ring-violet-100\"\n              />\n              <input\n                value={email}\n                onChange={(e) => setEmail(e.target.value)}\n                placeholder=\"Email\"\n                type=\"email\"\n                className=\"w-full rounded-lg border border-slate-200 px-3 py-2.5 text-sm outline-none transition-colors focus:border-violet-400 focus:ring-2 focus:ring-violet-100\"\n              />\n              <select\n                value={roleId}\n                onChange={(e) => setRoleId(e.target.value)}\n                className=\"w-full rounded-lg border border-slate-200 px-3 py-2.5 text-sm outline-none transition-colors focus:border-violet-400 focus:ring-2 focus:ring-violet-100\"\n              >\n                {jobPostings.map((j) => (\n                  <option key={j.id} value={j.id}>\n                    {j.title}\n                  </option>\n                ))}\n              </select>\n              <textarea\n                value={resumeNotes}\n                onChange={(e) => setResumeNotes(e.target.value)}\n                placeholder=\"Resume notes (optional)\"\n                rows={3}\n                className=\"w-full rounded-lg border border-slate-200 px-3 py-2.5 text-sm outline-none transition-colors focus:border-violet-400 focus:ring-2 focus:ring-violet-100\"\n              />\n              <div className=\"flex items-center gap-2.5 pt-1\">\n                <span className=\"text-xs font-medium text-slate-600\">Rating</span>\n                <StarRating rating={rating} onChange={setRating} />\n              </div>\n              {error && <p className=\"text-sm font-medium text-red-600\">{error}</p>}\n            </form>\n            <div className=\"flex justify-end gap-2 border-t border-slate-100 px-5 py-4 sm:px-6\">\n              <button\n                type=\"button\"\n                onClick={onClose}\n                className=\"rounded-lg px-4 py-2.5 text-sm font-medium text-slate-600 transition-colors hover:bg-slate-100\"\n              >\n                Cancel\n              </button>\n              <button\n                type=\"submit\"\n                form=\"new-candidate-form\"\n                className=\"rounded-lg bg-gradient-to-r from-violet-600 to-indigo-600 px-4 py-2.5 text-sm font-semibold text-white shadow-sm shadow-violet-500/30 transition-all duration-150 hover:shadow-md active:scale-[0.98]\"\n              >\n                Add candidate\n              </button>\n            </div>\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n",
  "src/components/StarRating.tsx": "import { Star } from \"lucide-react\";\n\ninterface Props {\n  rating: number;\n  onChange?: (rating: number) => void;\n  size?: \"sm\" | \"md\";\n}\n\nexport function StarRating({ rating, onChange, size = \"sm\" }: Props) {\n  const dim = size === \"sm\" ? \"h-3.5 w-3.5\" : \"h-5 w-5\";\n  return (\n    <div className=\"flex items-center gap-0.5\">\n      {[1, 2, 3, 4, 5].map((n) => (\n        <button\n          key={n}\n          type=\"button\"\n          disabled={!onChange}\n          onClick={(e) => {\n            e.stopPropagation();\n            onChange?.(rating === n ? 0 : n);\n          }}\n          className={`-m-1 rounded p-1 transition-transform ${onChange ? \"cursor-pointer hover:scale-110 active:scale-95\" : \"cursor-default\"}`}\n          title={onChange ? `Rate ${n} star${n > 1 ? \"s\" : \"\"}` : undefined}\n        >\n          <Star className={`${dim} transition-colors ${n <= rating ? \"fill-amber-400 text-amber-400\" : \"fill-none text-slate-300\"}`} />\n        </button>\n      ))}\n    </div>\n  );\n}\n",
  "src/index.css": "@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\nhtml {\n  -webkit-font-smoothing: antialiased;\n}\n\nbody {\n  font-family: \"Inter\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n}\n\n::-webkit-scrollbar {\n  height: 8px;\n  width: 8px;\n}\n\n::-webkit-scrollbar-thumb {\n  background-color: rgba(0, 0, 0, 0.15);\n  border-radius: 9999px;\n}\n",
  "src/lib/seedData.ts": "import type { Candidate, JobPosting } from \"../types\";\n\n// ---------------------------------------------------------------------------\n// DEMO DATA ONLY. This file exists so the board isn't empty the very first\n// time you open the app — every job posting, candidate, and note below is\n// fake. It's loaded once by lib/storage.ts (only when localStorage has\n// never held postings/candidates before) and after that behaves exactly\n// like anything you type in yourself: fully editable and deletable, and it\n// will NOT come back once you clear it out.\n// ---------------------------------------------------------------------------\n\nconst DAY = 24 * 60 * 60 * 1000;\n\nfunction ago(ms: number): number {\n  return Date.now() - ms;\n}\n\nexport function seedJobPostings(): JobPosting[] {\n  return [\n    { id: \"role-fe\", title: \"Senior Frontend Engineer\", department: \"Engineering\", status: \"open\", createdAt: ago(30 * DAY) },\n    { id: \"role-pd\", title: \"Product Designer\", department: \"Design\", status: \"open\", createdAt: ago(21 * DAY) },\n    { id: \"role-da\", title: \"Data Analyst\", department: \"Data\", status: \"open\", createdAt: ago(14 * DAY) },\n    { id: \"role-sm\", title: \"Social Media Manager\", department: \"Marketing\", status: \"closed\", createdAt: ago(60 * DAY) },\n  ];\n}\n\nexport function seedCandidates(): Candidate[] {\n  return [\n    {\n      id: \"cand-1\",\n      name: \"Maya Torres\",\n      email: \"maya.torres@mailbox.com\",\n      roleId: \"role-fe\",\n      resumeNotes: \"6 years React/TypeScript, led a design-system rewrite at her last company. Strong portfolio, clean GitHub history.\",\n      rating: 0,\n      stage: \"Applied\",\n      createdAt: ago(2 * DAY),\n      activity: [{ id: \"cand-1-a1\", text: \"Application received via careers page.\", createdAt: ago(2 * DAY) }],\n    },\n    {\n      id: \"cand-2\",\n      name: \"Ibrahim Al-Sayed\",\n      email: \"ibrahim.alsayed@quickmail.net\",\n      roleId: \"role-fe\",\n      resumeNotes: \"8 years full-stack, mostly backend-leaning. Not a strong frontend fit but a solid engineer overall.\",\n      rating: 3,\n      stage: \"Screening\",\n      createdAt: ago(6 * DAY),\n      activity: [\n        { id: \"cand-2-a1\", text: \"Application received.\", createdAt: ago(6 * DAY) },\n        { id: \"cand-2-a2\", text: \"Recruiter screen scheduled for Thursday.\", createdAt: ago(2 * DAY) },\n      ],\n    },\n    {\n      id: \"cand-3\",\n      name: \"Priya Chandrasekar\",\n      email: \"priya.c@mailhaven.io\",\n      roleId: \"role-fe\",\n      resumeNotes: \"Ex-startup lead frontend engineer, built a component library from scratch. Great communicator in the phone screen.\",\n      rating: 5,\n      stage: \"Interview\",\n      createdAt: ago(10 * DAY),\n      activity: [\n        { id: \"cand-3-a1\", text: \"Application received.\", createdAt: ago(10 * DAY) },\n        { id: \"cand-3-a2\", text: \"Phone screen: excellent. Moving to onsite loop.\", createdAt: ago(5 * DAY) },\n        { id: \"cand-3-a3\", text: \"Onsite scheduled for next Tuesday, 4 interviewers.\", createdAt: ago(1 * DAY) },\n      ],\n    },\n    {\n      id: \"cand-4\",\n      name: \"Devon Marsh\",\n      email: \"devon.marsh@getpost.com\",\n      roleId: \"role-pd\",\n      resumeNotes: \"Product designer with strong systems-thinking background, previously at a mid-size B2B SaaS company.\",\n      rating: 4,\n      stage: \"Offer\",\n      createdAt: ago(18 * DAY),\n      activity: [\n        { id: \"cand-4-a1\", text: \"Application received.\", createdAt: ago(18 * DAY) },\n        { id: \"cand-4-a2\", text: \"Onsite loop completed — unanimous positive feedback.\", createdAt: ago(6 * DAY) },\n        { id: \"cand-4-a3\", text: \"Offer approved by hiring committee, sending today.\", createdAt: ago(1 * DAY) },\n      ],\n    },\n    {\n      id: \"cand-5\",\n      name: \"Naomi Reyes\",\n      email: \"naomi.reyes@fastmail.co\",\n      roleId: \"role-pd\",\n      resumeNotes: \"Junior designer, promising portfolio but limited experience with complex enterprise flows.\",\n      rating: 2,\n      stage: \"Applied\",\n      createdAt: ago(1 * DAY),\n      activity: [{ id: \"cand-5-a1\", text: \"Application received via referral.\", createdAt: ago(1 * DAY) }],\n    },\n    {\n      id: \"cand-6\",\n      name: \"Lucas Ferreira\",\n      email: \"lucas.ferreira@inboxpro.com\",\n      roleId: \"role-da\",\n      resumeNotes: \"SQL and Python heavy, worked on churn analysis and cohort dashboards at a subscription company.\",\n      rating: 4,\n      stage: \"Interview\",\n      createdAt: ago(9 * DAY),\n      activity: [\n        { id: \"cand-6-a1\", text: \"Application received.\", createdAt: ago(9 * DAY) },\n        { id: \"cand-6-a2\", text: \"Take-home analysis exercise sent.\", createdAt: ago(6 * DAY) },\n        { id: \"cand-6-a3\", text: \"Take-home reviewed — strong SQL, clear writeup. Scheduling panel.\", createdAt: ago(2 * DAY) },\n      ],\n    },\n    {\n      id: \"cand-7\",\n      name: \"Grace Kim\",\n      email: \"grace.kim@mailwave.net\",\n      roleId: \"role-da\",\n      resumeNotes: \"Strong academic background but no industry experience yet. Eager and quick learner in the screen.\",\n      rating: 0,\n      stage: \"Screening\",\n      createdAt: ago(4 * DAY),\n      activity: [\n        { id: \"cand-7-a1\", text: \"Application received.\", createdAt: ago(4 * DAY) },\n        { id: \"cand-7-a2\", text: \"Recruiter screen completed, notes pending.\", createdAt: ago(1 * DAY) },\n      ],\n    },\n    {\n      id: \"cand-8\",\n      name: \"Tomas Nowak\",\n      email: \"tomas.nowak@quickbox.io\",\n      roleId: \"role-fe\",\n      resumeNotes: \"Solid resume but two no-shows for scheduled calls. Passing for now.\",\n      rating: 1,\n      stage: \"Rejected\",\n      createdAt: ago(15 * DAY),\n      activity: [\n        { id: \"cand-8-a1\", text: \"Application received.\", createdAt: ago(15 * DAY) },\n        { id: \"cand-8-a2\", text: \"Missed recruiter screen twice, no response to reschedule. Closing out.\", createdAt: ago(8 * DAY) },\n      ],\n    },\n    {\n      id: \"cand-9\",\n      name: \"Fatima Zahra\",\n      email: \"fatima.zahra@mailhub.org\",\n      roleId: \"role-pd\",\n      resumeNotes: \"Started as a contractor, converted after 3 months of strong design work on the onboarding flow.\",\n      rating: 5,\n      stage: \"Hired\",\n      createdAt: ago(45 * DAY),\n      activity: [\n        { id: \"cand-9-a1\", text: \"Application received.\", createdAt: ago(45 * DAY) },\n        { id: \"cand-9-a2\", text: \"Offer accepted — start date set.\", createdAt: ago(30 * DAY) },\n        { id: \"cand-9-a3\", text: \"Onboarded, first day went great.\", createdAt: ago(28 * DAY) },\n      ],\n    },\n    {\n      id: \"cand-10\",\n      name: \"Ben Okafor\",\n      email: \"ben.okafor@postnest.com\",\n      roleId: \"role-da\",\n      resumeNotes: \"Data analyst background, interested but salary expectations were well above the posted range.\",\n      rating: 2,\n      stage: \"Rejected\",\n      createdAt: ago(12 * DAY),\n      activity: [\n        { id: \"cand-10-a1\", text: \"Application received.\", createdAt: ago(12 * DAY) },\n        { id: \"cand-10-a2\", text: \"Comp expectations mismatch after screen — closing out respectfully.\", createdAt: ago(7 * DAY) },\n      ],\n    },\n  ];\n}\n",
  "src/lib/storage.ts": "import type { ActivityEntry, Candidate, JobPosting, JobStatus, Stage } from \"../types\";\nimport { STAGES } from \"../types\";\nimport { seedCandidates, seedJobPostings } from \"./seedData\";\n\nconst JOBS_KEY = \"applicant-tracker:jobs\";\nconst CANDIDATES_KEY = \"applicant-tracker:candidates\";\n\nfunction isJobStatus(value: unknown): value is JobStatus {\n  return value === \"open\" || value === \"closed\";\n}\n\nfunction isJobPosting(value: unknown): value is JobPosting {\n  if (!value || typeof value !== \"object\") return false;\n  const j = value as Record<string, unknown>;\n  return (\n    typeof j.id === \"string\" &&\n    typeof j.title === \"string\" &&\n    typeof j.department === \"string\" &&\n    isJobStatus(j.status) &&\n    typeof j.createdAt === \"number\"\n  );\n}\n\nfunction isStage(value: unknown): value is Stage {\n  return typeof value === \"string\" && STAGES.includes(value as Stage);\n}\n\nfunction isActivityEntry(value: unknown): value is ActivityEntry {\n  if (!value || typeof value !== \"object\") return false;\n  const a = value as Record<string, unknown>;\n  return typeof a.id === \"string\" && typeof a.text === \"string\" && typeof a.createdAt === \"number\";\n}\n\nfunction isCandidate(value: unknown): value is Candidate {\n  if (!value || typeof value !== \"object\") return false;\n  const c = value as Record<string, unknown>;\n  return (\n    typeof c.id === \"string\" &&\n    typeof c.name === \"string\" &&\n    typeof c.email === \"string\" &&\n    typeof c.roleId === \"string\" &&\n    typeof c.resumeNotes === \"string\" &&\n    typeof c.rating === \"number\" &&\n    isStage(c.stage) &&\n    Array.isArray(c.activity) &&\n    typeof c.createdAt === \"number\"\n  );\n}\n\nexport function loadJobPostings(): JobPosting[] {\n  try {\n    const raw = localStorage.getItem(JOBS_KEY);\n    if (raw === null) {\n      // Never saved before — seed demo postings. See src/lib/seedData.ts:\n      // this is fake data, and once you clear it out (saveJobPostings\n      // persists the empty array) it will not be re-seeded.\n      const seeded = seedJobPostings();\n      saveJobPostings(seeded);\n      return seeded;\n    }\n    const parsed = JSON.parse(raw);\n    return Array.isArray(parsed) ? parsed.filter(isJobPosting) : [];\n  } catch {\n    return [];\n  }\n}\n\nexport function saveJobPostings(jobs: JobPosting[]): void {\n  try {\n    localStorage.setItem(JOBS_KEY, JSON.stringify(jobs));\n  } catch {\n    // Storage full or unavailable — in-memory state still works this session.\n  }\n}\n\nexport function loadCandidates(): Candidate[] {\n  try {\n    const raw = localStorage.getItem(CANDIDATES_KEY);\n    if (raw === null) {\n      const seeded = seedCandidates();\n      saveCandidates(seeded);\n      return seeded;\n    }\n    const parsed = JSON.parse(raw);\n    if (!Array.isArray(parsed)) return [];\n    return parsed.filter(isCandidate).map((c) => ({ ...c, activity: c.activity.filter(isActivityEntry) }));\n  } catch {\n    return [];\n  }\n}\n\nexport function saveCandidates(candidates: Candidate[]): void {\n  try {\n    localStorage.setItem(CANDIDATES_KEY, JSON.stringify(candidates));\n  } catch {\n    // Ignore — see saveJobPostings.\n  }\n}\n",
  "src/main.tsx": "import React from \"react\";\nimport ReactDOM from \"react-dom/client\";\nimport App from \"./App\";\nimport \"./index.css\";\n\nReactDOM.createRoot(document.getElementById(\"root\")!).render(\n  <React.StrictMode>\n    <App />\n  </React.StrictMode>\n);\n",
  "src/types.ts": "export type Stage = \"Applied\" | \"Screening\" | \"Interview\" | \"Offer\" | \"Hired\" | \"Rejected\";\n\nexport const STAGES: Stage[] = [\"Applied\", \"Screening\", \"Interview\", \"Offer\", \"Hired\", \"Rejected\"];\n\nexport type JobStatus = \"open\" | \"closed\";\n\nexport interface JobPosting {\n  id: string;\n  title: string;\n  department: string;\n  status: JobStatus;\n  createdAt: number;\n}\n\nexport interface ActivityEntry {\n  id: string;\n  text: string;\n  createdAt: number;\n}\n\nexport interface Candidate {\n  id: string;\n  name: string;\n  email: string;\n  roleId: string;\n  resumeNotes: string;\n  rating: number; // 0-5, 0 = not yet rated\n  stage: Stage;\n  activity: ActivityEntry[];\n  createdAt: number;\n}\n\nexport function clampRating(n: number): number {\n  return Math.max(0, Math.min(5, Math.round(n)));\n}\n",
  "tailwind.config.js": "/** @type {import('tailwindcss').Config} */\nexport default {\n  content: [\"./index.html\", \"./src/**/*.{js,ts,jsx,tsx}\"],\n  theme: {\n    extend: {},\n  },\n  plugins: [],\n};\n",
  "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"useDefineForClassFields\": true,\n    \"lib\": [\"ES2020\", \"DOM\", \"DOM.Iterable\"],\n    \"module\": \"ESNext\",\n    \"skipLibCheck\": true,\n    \"moduleResolution\": \"bundler\",\n    \"allowImportingTsExtensions\": true,\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"noEmit\": true,\n    \"jsx\": \"react-jsx\",\n    \"strict\": true,\n    \"noUnusedLocals\": true,\n    \"noUnusedParameters\": true,\n    \"noFallthroughCasesInSwitch\": true\n  },\n  \"include\": [\"src\"],\n  \"references\": [{ \"path\": \"./tsconfig.node.json\" }]\n}\n",
  "tsconfig.node.json": "{\n  \"compilerOptions\": {\n    \"composite\": true,\n    \"skipLibCheck\": true,\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"allowSyntheticDefaultImports\": true,\n    \"strict\": true\n  },\n  \"include\": [\"vite.config.ts\"]\n}\n",
  "vite.config.ts": "import { defineConfig } from \"vite\";\nimport react from \"@vitejs/plugin-react\";\n\nexport default defineConfig({\n  plugins: [react()],\n});\n",
};
